        <Suspense fallback={<p>Loading related products...</p>}>
          <RelatedProducts />
        </Suspense>
      </section>
    </main>
  )
}

async function RelatedProducts() {
  // Keep related products out of the App Shell that every link prefetches.
  // They still resolve on a per-link prefetch (<Link prefetch={true}>).
  await prefetch()
  const relatedProducts = await getRelatedProducts()

  return (
    <ul>
      {relatedProducts.map((product) => (
        <li key={product}>{product}</li>
      ))}
    </ul>
  )
}

